')print(&quot;*&quot; * 50)# load binfile into arraybinfile = open('./ReverseMe3.EXE', 'rb')bindata = binfile.read()binfile.close()# set architecturepwn.context.arch = 'amd64'entry_va = 0x401000 # virtual address of entry pointcodestart_pa = pe.sections[0].PointerToRawData # physical address of entry point in binarycodestart = codestart_pacodelen = 0x258 # length of code to decryptxor_offset = 0x30 # length after which program starts xorring# code uses xor decryptionbindata = list(bindata)for key in range(255): for i in range(codelen): bindata[codestart + xor_offset + i] ^= key code = pwn.disasm(bytearray(bindata[codestart:codestart+codelen])) if('(bad)' not in code): print(f'******************************* key = {hex(key)} ***********************************') print(code) Check for valid disassembly in this. I got 0x64 to be the valid key. I then created a script to decrypt this and patch the binary. 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657#!/usr/bin/env python3# Reference : https://bufferoverflows.net/exploring-pe-files-with-python/import pefileimport pwn# load pe filepe = pefile.PE(&quot;./ReverseMe3.EXE&quot;)pe.print_info()# print section informationfor section in pe.sections: print(section.Name.decode().rstrip('\x00') +\ &quot;
